from collections import OrderedDict, deque

refs = [1, 2, 3, 4, 1, 2, 5, 1, 2, 3, 4, 5]

def fifo_faults(refs, frames):
    mem, faults = deque(), 0
    for page in refs:
        if page not in mem:
            faults += 1
            if len(mem) == frames:
                mem.popleft()          # evict the oldest arrival
            mem.append(page)
    return faults

def lru_faults(refs, frames):
    mem, faults = OrderedDict(), 0
    for page in refs:
        if page in mem:
            mem.move_to_end(page)      # mark as most recently used
        else:
            faults += 1
            if len(mem) == frames:
                mem.popitem(last=False)  # evict the least recently used
            mem[page] = True
    return faults

for frames in range(1, 6):
    print(f"{frames} frames: FIFO={fifo_faults(refs, frames):2}  LRU={lru_faults(refs, frames):2}")
